import pytest
import csv
import os
import sys
from pathlib import Path

# Add parent directory to path to allow imports from code/
sys.path.insert(0, os.path.join(os.path.dirname(__file__), '..', 'code'))

# Note: In a real CI/CD environment, we would run the actual pipeline scripts
# here. For this unit test, we simulate the expected structure of the output
# based on the requirements of T012.

# We assume the fixture file exists or is generated by T013/T014 before this runs.
# If the file doesn't exist, we skip the test or raise a clear error.
FIXTURE_PATH = Path(__file__).parent / "fixtures" / "us1_subset.csv"
OUTPUT_PATH = Path(__file__).parent / ".." / ".." / "data" / "processed" / "matched_pairs.csv"

def test_pipeline_output_structure():
    """
    Integration test for US1 subset.
    Asserts row_count == 10 AND all(p_value is not null) in the final output.
    """
    # Check if the expected output file exists
    if not OUTPUT_PATH.exists():
        # If the file doesn't exist, it implies the pipeline (T013-T014) hasn't run yet.
        # In a real CI, this would be a failure. Here we raise a clear error.
        pytest.fail(f"Pipeline output file not found at {OUTPUT_PATH}. Ensure T013-T014 have run successfully.")

    # Read the CSV
    with open(OUTPUT_PATH, 'r', newline='', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        rows = list(reader)

    # Requirement from T012: Assert row_count == 10 (for the subset)
    # Note: The actual count might vary if the full pipeline ran on more data.
    # The task description says "Use fixture ... Assert row_count == 10".
    # We will assert that there are *at least* 10 rows if the fixture was the input,
    # or exactly 10 if the fixture was the only thing processed.
    # Given the ambiguity, we assert >= 10 to be safe for a "subset" run.
    # However, T012 specifically says "Assert row_count == 10".
    # Let's assume the pipeline was run specifically on the 10-row fixture.
    if len(rows) != 10:
        # If the test environment has more data, this might fail. 
        # We'll check if it's the specific subset test.
        # For the purpose of this implementation, we assert the condition strictly as requested.
        # If the actual data has more, the test logic in a real runner would filter to the subset.
        # Here we assume the file IS the subset.
        pytest.fail(f"Expected exactly 10 rows in matched_pairs.csv, found {len(rows)}.")

    # Requirement: all(p_value is not null)
    # Check both pre-print and journal p-values
    for i, row in enumerate(rows):
        pp_p = row.get('preprint_p_value')
        jrnl_p = row.get('journal_p_value')
        
        if pp_p is None or pp_p == '':
            pytest.fail(f"Row {i} has missing preprint p-value.")
        if jrnl_p is None or jrnl_p == '':
            pytest.fail(f"Row {i} has missing journal p-value.")

def test_fixture_exists():
    """Verify the test fixture file exists."""
    if not FIXTURE_PATH.exists():
        # Create a minimal fixture if missing to allow the test to run in isolation
        # This is a fallback for local testing; in CI, the fixture should be provided.
        FIXTURE_PATH.parent.mkdir(parents=True, exist_ok=True)
        with open(FIXTURE_PATH, 'w', newline='', encoding='utf-8') as f:
            writer = csv.writer(f)
            writer.writerow(['id', 'title', 'preprint_doi', 'journal_doi', 'preprint_p_value', 'journal_p_value'])
            for i in range(10):
                writer.writerow([f'row_{i}', f'Title {i}', f'10.1234/arxiv.{i}', f'10.1234/journal.{i}', f'0.0{i}', f'0.0{i+1}'])
        pytest.xfail("Fixture was generated on the fly; please ensure T013 generates the real fixture.")
